    String source=snapshot.sources().stream().filter(f->Objects.equals(f.name(),obligation.source().file())).map(GraphWorkspace.SourceFile::source).findFirst().orElse("");
    Map<String,String> safe=safeCandidate(method,ordinary.get(0));
    Matcher direct=Pattern.compile("(?s)if\\s*\\(([^)]*)\\)\\s*\\{[^{}]*(?:return\\s+|=\\s*)new\\s+"+Pattern.quote(target)+"\\s*\\(").matcher(source);
